mapper.sql:
r.deleted=0 and ${scope}

    and (r.requisition_no like concat('%', #{keyword}, '%') or r.purpose like concat('%', #{keyword}, '%'))


    and r.status=#{status}

mapper.update:
update pr_requisition
set required_date=#{requiredDate}, purpose=#{purpose}, budget_amount=#{budgetAmount},
    status='DRAFT', rejection_reason=null, cancellation_reason=null, process_instance_id=null,
    updated_by=#{userId}
where id=#{id}

update pr_requisition
set status=#{status}, process_instance_id=#{processInstanceId},
    rejection_reason=null, cancellation_reason=null, updated_by=#{userId}
where id=#{id}

update pr_requisition
set status='CANCELLED', cancellation_reason=#{reason}, process_instance_id=null, updated_by=#{userId}
where id=#{id}
